  public static long NormalizeHeroXp(FoundationValue value)=>LegacySaveImporter.NormalizeHeroXp(value);public static int HeroThreshold(int level){int n=Math.Max(1,Math.Min(MaxHeroLevel,level));return 25*(n-1)*n;}public static int LevelFor(long total){int n=1;while(n<MaxHeroLevel&&total>=HeroThreshold(n+1))n++;return n;}
