  public string WeaponUpgradeReason(string target){if(!Catalogs.Require("weaponUpgrades").TryGet(target,out var recipe))return Tr("Geen volgende wapenupgrade.");if(target=="star")return Tr("Versla De Vergeten Wachter onder de Kristaltempel.");if(State.Get("weapon").AsString()!=recipe.Require("from").AsString())return Tr("Volg eerst de bestaande zwaardverbetering.");if(!nearGreta||!State.InGame||State.Ended||State.Transitioning)return Tr("Praat met Greta om te laten smeden.");if(State.Coins<recipe.Require("coins").AsInt64())return Tr("Niet genoeg munten.");foreach(var input in recipe.Require("materials").Entries)if(State.Count(input.Key.AsString())<input.Value.AsInt64())return F("Te weinig: %s",Inventory.ItemName(input.Key.AsString()));return "";}
