  public string UpgradeReason(string recipeId){if(!Catalogs.Require("upgradeRecipes").TryGet(recipeId,out var recipe))return Tr(Catalogs.Require("stationText").Require("unknown").AsString());if(recipe.TryGet("unlock",out var unlock)&&!State.Flag(unlock.AsString()))return Tr(G(recipe,"unlock_hint",S("Nog vergrendeld: herstel de prismabank of Mees’ oversteek.")).AsString());string skill=recipe.Require("skill").AsString();if(SkillLevel(skill)<recipe.Require("level").AsInt64())return F(Catalogs.Require("stationText").Require("skill_required").AsString(),Tr(Catalogs.Require("skills").Require(skill).Require("name").AsString()),recipe.Require("level").AsInt64());string station=G(recipe,"station",S("")).AsString();if(station!=""&&State.MapId!=station)return F(Catalogs.Require("stationText").Require("station_required").AsString(),Tr(Catalogs.Require("stationText").Require(station).AsString()));string output=recipe.Require("output").AsString();if(Inventory.Room(output)<N(G(recipe,"amount",I(1))))return F(Catalogs.Require("stationText").Require("full").AsString(),Inventory.ItemName(output));foreach(var input in recipe.Require("inputs").Entries)if(Available(input.Key.AsString())<input.Value.AsInt64())return F(Catalogs.Require("stationText").Require("missing").AsString(),Inventory.ItemName(input.Key.AsString()));return "";}
  void EnsureProfessionState()
  {
   var raw=State.Get("professions");if(raw.TryGet("xp",out _)&&raw.TryGet("cooldowns",out _))return;
   var normalized=importer.Import(System.Text.Encoding.UTF8.GetBytes(FoundationJson.StringifyPlain(State.Snapshot()))).State.Get("professions");
   foreach(var row in raw.Entries)if(!normalized.TryGet(row.Key.AsString(),out _))normalized=R(normalized,row.Key.AsString(),row.Value);
   foreach(string field in new[]{"xp","cooldowns"}){var table=G(normalized,field,E());var original=G(raw,field,E());if(original.Kind=="object"||original.Kind=="dictionary")foreach(var row in original.Entries)if(!table.TryGet(row.Key.AsString(),out _))table=R(table,row.Key.AsString(),row.Value);normalized=R(normalized,field,table);}
   State.Set("professions",normalized);
  }
  public bool UpgradeGear(string recipeId){if(busy)return false;busy=true;try{EnsureProfessionState();LastMessage=UpgradeReason(recipeId);if(LastMessage!="")return false;var recipe=Catalogs.Require("upgradeRecipes").Require(recipeId);string old=recipe.Require("upgrade_from").AsString(),output=recipe.Require("output").AsString(),slot=SlotOf(old);bool worn=Equipped(slot)==old;string kind=Inventory.NearbyKind;var bag=State.Get("inventory");var stock=kind=="home"?HomeState().Require("home"):kind=="coast"?State.Get("coastal_storage"):E();foreach(var input in recipe.Require("inputs").Entries){string id=input.Key.AsString();long n=input.Value.AsInt64(),fromBag=Math.Min(N(G(bag,id,I(0))),n);bag=Remove(bag,id,fromBag);if(n>fromBag)stock=Remove(stock,id,n-fromBag);}var equipment=NormalizeEquipment(State.Get("equipment"),bag);var clothing=NormalizeClothing(State.Get("clothing"),bag);long amount=N(G(recipe,"amount",I(1)));bag=R(bag,output,I(N(G(bag,output,I(0)))+amount));if(worn)equipment=R(equipment,slot,S(output));var professions=State.Get("professions");var xp=G(professions,"xp",E());string skill=recipe.Require("skill").AsString();long previous=N(G(xp,skill,I(0)));professions=R(professions,"xp",R(xp,skill,I(previous+Math.Min(recipe.Require("xp").AsInt64(),1350-previous))));if(G(professions,"goal",S("")).AsString()==recipeId)professions=R(professions,"goal",S(""));var changes=new Dictionary<string,FoundationValue>{{"inventory",bag},{"equipment",equipment},{"clothing",clothing},{"professions",professions}};if(kind=="home")changes["stockroom"]=R(HomeState(),"home",stock);else if(kind=="coast")changes["coastal_storage"]=stock;var staged=State.Snapshot();foreach(var p in changes)staged=R(staged,p.Key,p.Value);changes["quests"]=RefreshQuests(staged);Apply(changes,true,true);LastMessage=F(Catalogs.Require("stationText").Require("made").AsString(),Inventory.ItemName(output),amount);return true;}finally{busy=false;}}
